!function() {
    this.EmojiPicker = function() {
        function EmojiPicker(options) {
            var iconSize, assetsPath;
            if (options == null) options = {};
            $.emojiarea.iconSize = (iconSize = options.iconSize) != null ? iconSize : 25;
            $.emojiarea.assetsPath = (assetsPath = options.assetsPath) != null ? assetsPath : "";
            this.generateEmojiIconSets(options);
            if (!options.emojiable_selector) options.emojiable_selector = "[data-emojiable=true]";
            this.options = options;
        }

        EmojiPicker.prototype.discover = function() {
            if (!(/iPad|iPhone|iPod/.test(navigator.userAgent) && !window.MSStream)) {
                return $(this.options.emojiable_selector).emojiarea($.extend({
                    emojiPopup: this,
                    norealTime: true
                }, this.options));
            }
        };

        // EmojiPicker.prototype.discover = function() {
        //     // 直接返回初始化代碼，不進行 iOS 檢測
        //     return $(this.options.emojiable_selector).emojiarea($.extend({
        //         emojiPopup: this,
        //         norealTime: true
        //     }, this.options));
        // };

        EmojiPicker.prototype.generateEmojiIconSets = function(options) {
            let icons = {}, reverseIcons = {}, categoryIndex, emojiIndex, emoji, spriteSheetDimens, row, col, category, emojiName;
            for (categoryIndex = 0; categoryIndex < Config.EmojiCategories.length; categoryIndex++) {
                spriteSheetDimens = Config.EmojiCategorySpritesheetDimens[categoryIndex][1];
                for (emojiIndex = 0; emojiIndex < Config.EmojiCategories[categoryIndex].length; emojiIndex++) {
                    emoji = Config.Emoji[Config.EmojiCategories[categoryIndex][emojiIndex]];
                    emojiName = emoji[1][0];
                    row = Math.floor(emojiIndex / spriteSheetDimens);
                    col = emojiIndex % spriteSheetDimens;
                    icons[":" + emojiName + ":"] = [categoryIndex, row, col, ":" + emojiName + ":"];
                    reverseIcons[emojiName] = emoji[0];
                }
            }
            $.emojiarea.icons = icons;
            $.emojiarea.reverseIcons = reverseIcons;
        };

        EmojiPicker.prototype.colonToUnicode = function(text) {
            if (!text) return "";
            if (!Config.rx_colons) Config.init_unified();
            return text.replace(Config.rx_colons, match => Config.mapcolon[match] || "");
        };

        EmojiPicker.prototype.appendUnicodeAsImageToElement = function(element, text) {
            let parts, part, icon, textNode;
            if (!text) return "";
            if (!Config.rx_colons) Config.init_unified();
            parts = text.split(Config.rx_codes);
            for (let i = 0; i < parts.length; i++) {
                part = parts[i];
                icon = "";
                if (Config.rx_codes.test(part)) {
                    if (icon = Config.reversemap[part]) {
                        icon = ":" + icon + ":";
                        icon = $.emojiarea.createIcon($.emojiarea.icons[icon]);
                    }
                } else {
                    icon = document.createTextNode(part);
                }
                element.append(icon);
            }
            return text.replace(Config.rx_codes, match => {
                if (icon = Config.reversemap[match]) {
                    icon = ":" + icon + ":";
                    return $.emojiarea.createIcon($.emojiarea.icons[icon]);
                }
                return "";
            });
        };

        EmojiPicker.prototype.colonToImage = function(text) {
            if (!text) return "";
            if (!Config.rx_colons) Config.init_unified();
            return text.replace(Config.rx_colons, match => match ? $.emojiarea.createIcon($.emojiarea.icons[match]) : "");
        };

        return EmojiPicker;
    }();
}();
